/**
 * `npm run db:access-link -- <correo>`: an access link, generated by whoever operates the server, for someone who can't get
 * in during an attack and has no working e-mail. Prints it once, to be delivered by another channel after confirming who
 * asks; it replaces the account's earlier links, lasts 60 minutes, is audited, and an attacker's recovery requests can't
 * revoke it (it is issued as INVITACION, audit IND2-04). Using it sets a new password
 * and trusts that browser (api/password.ts). Requires access to the server: it is not reachable through the API.
 */
import { randomBytes } from 'node:crypto';
import { audit, localDateTime, sha256 } from './auth.ts';
import { RESET_TOKEN_MINUTES } from './mail.ts';
import { transaction } from './password.ts';
import { createPool } from './server.ts';

if (import.meta.main) {
  const email = process.argv[2]?.trim().toLowerCase();
  if (!email) {
    console.error('Uso: npm run db:access-link -- <correo>');
    process.exit(1);
  }
  const db = createPool(process.env);
  const token = randomBytes(32).toString('base64url');
  try {
    const found = await transaction(db, async (tx) => {
      const [user]: { id: number }[] = await tx.query(
        'SELECT id FROM usuarios WHERE email = ? AND activo FOR UPDATE',
        [email],
      );
      if (!user) return false;
      const now = localDateTime();
      await tx.query(
        `UPDATE tokens_recuperacion SET usado_en = ?
          WHERE usuario_id = ? AND usado_en IS NULL AND expira_en > ?`,
        [now, user.id, now],
      );
      await tx.query(
        // A recovery request only revokes RECUPERACION: an attacker's can't undo this.
        `INSERT INTO tokens_recuperacion (usuario_id, finalidad, token_hash, creado_en, expira_en)
         VALUES (?, 'INVITACION', ?, ?, ?)`,
        [user.id, sha256(token), now, localDateTime(Date.now() + RESET_TOKEN_MINUTES * 60_000)],
      );
      await audit(
        tx,
        user.id,
        'EDITAR',
        'usuarios',
        user.id,
        'Enlace de acceso por consola',
        'consola',
        'usuarios',
      );
      return true;
    });
    if (!found) {
      console.error('No hay una cuenta activa con ese correo.');
      process.exitCode = 1;
    } else {
      if (!process.env['APP_URL'])
        console.error('Aviso: sin APP_URL, el enlace apunta a localhost.');
      const base = (process.env['APP_URL'] ?? 'http://localhost:4200').replace(/\/+$/, '');
      console.log(`${base}/reset-password?token=${token}`);
      console.error(
        `Válido ${RESET_TOKEN_MINUTES} min. Entrégalo por otro canal, tras confirmar la identidad.`,
      );
    }
  } finally {
    await db.end();
  }
}
